validators.fn:
!value || (
(
  model.employee.maritalStatus !== 'married'
  && fn.filter(model.children, { childAllowance: true, possession: true }).length > 0
)
|| (
  model.employee.sex === 'female'
  && model.employee.maritalStatus === 'married'
)
|| (
 model.taxCreditRequest.singleParent.checked
)
)
